commands.vault policy read payments-read:
# Policy: payments-read
# Grants read-only access to payments secrets

path "secret/data/payments/*" {
  capabilities = ["read", "list"]
}

path "secret/metadata/payments/*" {
  capabilities = ["read", "list"]
}

commands.vault policy read admin-policy:
# Policy: admin-policy
# Full admin access for platform team

path "secret/*" {
  capabilities = ["create", "read", "update", "delete", "list"]
}

path "sys/policies/*" {
  capabilities = ["create", "read", "update", "delete", "list"]
}

path "auth/*" {
  capabilities = ["create", "read", "update", "delete", "list", "sudo"]
}

path "sys/health" {
  capabilities = ["read", "sudo"]
}

commands.vault policy read cicd-deploy:
# Policy: cicd-deploy
# CI/CD pipeline access - read secrets, manage leases

path "secret/data/services/*" {
  capabilities = ["read", "list"]
}

path "secret/data/app/config" {
  capabilities = ["read"]
}

path "sys/leases/renew" {
  capabilities = ["update"]
}

path "transit/encrypt/deploy-key" {
  capabilities = ["update"]
}

path "transit/decrypt/deploy-key" {
  capabilities = ["update"]
}

commands.vault policy read db-rotate:
# Policy: db-rotate
# Database credential rotation

path "database/creds/payments-db" {
  capabilities = ["read"]
}

path "database/rotate-root/payments-db" {
  capabilities = ["update"]
}

path "sys/leases/revoke" {
  capabilities = ["update"]
}

commands.vault policy read monitoring-read:
# Policy: monitoring-read
# Prometheus/Grafana metrics scraping

path "sys/metrics" {
  capabilities = ["read"]
}

path "sys/health" {
  capabilities = ["read"]
}

path "sys/seal-status" {
  capabilities = ["read"]
}
